mapper.select:
SELECT chunk_id,(CASE WHEN LOWER(CONCAT(section_title,' ',chunk_text)) LIKE LOWER(#{term}) ESCAPE '!' THEN 1 ELSE 0 END) AS score
FROM knowledge_index_chunk WHERE index_version=#{version} AND brand_code=#{brand} AND document_type=#{type} AND region='CN_MAINLAND'
ORDER BY score DESC,chunk_id LIMIT #{limit}
